import { registerExternalServer } from '@projexlight/sdk-mcp-bridge';
const { id } = await registerExternalServer({
  tenant_id, name: 'their-salesforce-mcp',
  url: 'https://mcp.acme.com/salesforce/sse',
  auth: { kind: 'bearer', secret_ref: snowflake_token_ref },
  capability_tags: ['crm', 'salesforce'],
});

import { invokeTool } from '@projexlight/sdk-mcp-bridge';
const { content } = await invokeTool({
  tenant_id, persona_id,
  server_name: 'their-salesforce-mcp',
  tool: 'salesforce_create_lead',
  arguments: { first_name, last_name, email, source: 'projexcloud' },
});

import { exposeOwnSurface } from '@projexlight/sdk-mcp-bridge';
const { mcp_url } = await exposeOwnSurface({
  tenant_id, name: 'acme-projexcloud-tools',
  scope: ['sdk-tenant', 'sdk-billing', 'sdk-meter'],
  auth: { kind: 'jwt', issuer: tenant_id },
});

subscribeEvents('secrets.secret.rotated.v1', async (e) => {
  const regs = await findRegistrationsUsingSecret({ secret_ref: e.payload.ref });
  for (const r of regs) await reTestConnectivity({ registration_id: r.id });
});

// driven by the daily cron:
for (const reg of await listEnabledRegistrations({ tenant_id })) {
  await discoverCapabilities({ registration_id: reg.id });
}
